function deriveVolumetricFogResolvedExtent(surface, froxelTileSize = 4) {
  // Optical reconstruction owns screen-depth pixels; shadow froxels remain coarse.
  return { width: Math.max(1, Math.ceil(surface.width)), height: Math.max(1, Math.ceil(surface.height)), depth: 1 };
}
